const MINIMAL_COMPUTE_SPV: [u32; 35] = [
    0x0723_0203,
    0x0001_0000,
    0,
    5,
    0,
    (2 << 16) | 17,
    1,
    (3 << 16) | 14,
    0,
    1,
    (5 << 16) | 15,
    5,
    4,
    0x6e69_616d,
    0,
    (6 << 16) | 16,
    4,
    17,
    1,
    1,
    1,
    (2 << 16) | 19,
    1,
    (3 << 16) | 33,
    2,
    1,
    (5 << 16) | 54,
    1,
    4,
    0,
    2,
    (2 << 16) | 248,
    3,
    (1 << 16) | 253,
    (1 << 16) | 56,
];

fn main() {
    let sizes = abi();
    assert_eq!(sizes[0] as usize, size_of::<SwitchNvkStageInfo>());
    assert_eq!(sizes[1] as usize, size_of::<SwitchNvkStage>());
    assert!(sizes[2] > 0);

    let entry = b"main\0";
    let info = SwitchNvkStageInfo {
        spirv: MINIMAL_COMPUTE_SPV.as_ptr(),
        spirv_bytes: MINIMAL_COMPUTE_SPV.len() * size_of::<u32>(),
        entry: entry.as_ptr() as *const c_char,
        stage: VK_SHADER_STAGE_COMPUTE_BIT,
        specialization: null(),
        layout: 0,
        pipeline_flags: 0,
        pipeline_pnext: null(),
        stage_pnext: null(),
        sample_shading: false,
        split: false,
        half_targets: 0,
        const_push_mask: 0,
        const_push_words: [0; 32],
        center_frag_depth: 0,
        semantic: null(),
        portable_context: null(),
        portable: None,
        texs_f16: false,
        turned: false,
        xr_plane_bindings: [0; 6],
        unorm_targets: 0,
    };
    let layout = SwitchNakLayout {
        sets: null(),
        set_count: 0,
        create_flags: 0,
        push_ranges: null(),
        push_range_count: 0,
    };

    let mut stage: SwitchNvkStage = unsafe { zeroed() };
    let res = unsafe {
        switch_compile_stage(
            FROZEN_GM20B.0.as_ptr() as *const c_void,
            &info,
            &layout,
            &mut stage,
        )
    };
    assert_eq!(res, VK_SUCCESS, "switch_compile_stage failed: {res}");
    assert!(!stage.code.is_null() && stage.code_bytes > 0);

    let mut metrics = SwitchNvkStageMetrics::default();
    let ok = unsafe {
        switch_compile_stage_metrics(&stage, &mut metrics, size_of::<SwitchNvkStageMetrics>())
    };
    assert!(ok && metrics.code_bytes == stage.code_bytes);

    println!(
        "abi={:?} code_bytes={} instructions={} gprs={}",
        sizes, stage.code_bytes, metrics.instructions, metrics.gprs
    );
    unsafe {
        switch_compile_stage_finish(&mut stage);
    }
    assert_eq!(stage.owner, null_mut());
}
